const s = wb.getWorksheet('ExcelForum help');
const before = [6,7,8,9,10].map(r => s.getRange('K'+r).getValues()[0][0]);
log('before', JSON.stringify(before));
for (let r = 6; r <= 10; r++) {
  s.getRange('K'+r).setValue(`=LOOKUP(2,1/(($B$3:$B$13=H${r})*($A$3:$A$13<=J${r})),INDEX($C$3:$E$13,0,MATCH(I${r},$C$1:$E$1,0)))`);
}
const rows = [];
for (let r = 6; r <= 10; r++) {
  const c = s.getRange('K'+r).getCell();
  const check = await wb.evaluate(`=INDEX('ExcelForum help'!$C$3:$E$13,MATCH(1,INDEX(('ExcelForum help'!$B$3:$B$13=H${r})*('ExcelForum help'!$A$3:$A$13=MAXIFS('ExcelForum help'!$A$3:$A$13,'ExcelForum help'!$B$3:$B$13,'ExcelForum help'!H${r},'ExcelForum help'!$A$3:$A$13,"<="&'ExcelForum help'!J${r})),0),0),MATCH('ExcelForum help'!I${r},'ExcelForum help'!$C$1:$E$1,0))`.replace(/\(\('ExcelForum help'!\$B\$3:\$B\$13=H/,"(('ExcelForum help'!$B$3:$B$13='ExcelForum help'!H"));
  rows.push(['K'+r, c.getFormula(), c.getValue(), c.getText?.(), s.getRange('K'+r).getStyle().getNumberFormat?.(), check]);
}
log(rows.map(x=>JSON.stringify(x)).join('\n'));
s.getRange('H6:K10')

